do $$ declare r record; begin for r in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and p.proname like 'admin_%' and pg_get_functiondef(p.oid) like '%is_wenik_admin()%' loop execute format('revoke execute on function %s from public, anon',r.signature); execute format('grant execute on function %s to authenticated',r.signature); end loop; end $$;